mapper.select:
SELECT DISTINCT ON (sf.id)
,sc.id as sc_id, v.id as sc_video_id, sc.sub_id as sc_sub_id, sc.content_id, v.id as v_id, v.video_name as v_video_name, v.video_name_index as v_video_name_index, v.file_id as v_file_id, v.video_source as video_source, s.id as s_id, s.name as s_name, s.name_index as s_name_index, s.description as s_description, s.sub_img_id as s_sub_img_id, s.state as course_state, s.available_type as course_available_type
, COALESCE((select count(id) from gc_user_save_content where folder_id=sf.id and master_id=#{masterId}),0) as videoNum, (select gv.file_id from gc_user_save_content sc join pt_channel_content pcc on pcc.content_id = sc.content_id join gc_video gv on gv.id = pcc.content_id where sc.folder_id=sf.id and sc.master_id=#{masterId} order by sc.create_time asc limit 1) as firstVideoFileId from gc_user_save_folder sf left join gc_user_save_content sc on sc.folder_id = sf.id left join gc_video v on v.id = sc.content_id AND v.id IN (SELECT content_id FROM course_content) left join gc_subject s on s.id= v.origin_course_id left join sys_file fs on s.sub_img_id=fs.id left join sys_file f on v.file_id=f.id left join gc_user u on u.id = sf.user_id left join gc_user_info info on info.id = u.info_id left join sys_file uf on info.avatar_file_id = uf.id where 1=1
AND sf.user_id !=#{userId}
and (not sf.is_private) and sf.master_id=#{masterId}
AND sf.id in
#{folderId}
AND sf.id not in
#{myFolderId}
order by sf.id DESC, sf.create_time DESC, sc.create_time DESC

select count(1) from gc_user_save_folder
where 1=1

and id in

	#{folderId}


and user_id = #{userId}

SELECT count(1)
FROM gc_user_save_folder playlist
    LEFT JOIN gc_user_save_content_follow playlist_follow ON playlist_follow.folder_id = playlist.id AND playlist_follow.user_id = #{portalUser.userId}
WHERE playlist_follow.id IS NULL AND playlist.master_id = #{portalUser.masterId} AND playlist.is_private = false AND playlist.user_id != #{portalUser.userId}
